positive = {"good", "great", "tasty", "fast", "love", "excellent", "happy"}
negative = {"bad", "slow", "cold", "late", "hate", "poor", "rude"}

def sentiment(review):
    words = review.lower().replace(",", " ").replace(".", " ").replace("!", " ").split()
    score = 0
    for w in words:
        if w in positive:
            score += 1
        elif w in negative:
            score -= 1
    if score > 0:
        label = "Positive"
    elif score < 0:
        label = "Negative"
    else:
        label = "Neutral"
    return score, label

reviews = ["The biryani was tasty and delivery was fast!",
           "Food was cold and the rider was rude.",
           "Order arrived at 8 pm.",
           "Great, the food was late again."]
for r in reviews:
    print(sentiment(r), "<-", r)

