# A tiny rule-based chatbot for a school library
rules = {
    "timing": "The library is open from 9 am to 4 pm, Monday to Saturday.",
    "fine": "The late fine is Rs 2 per day per book.",
    "issue": "You can issue up to 2 books for 14 days with your ID card.",
}
keywords = {
    "timing": ["time", "open", "hours", "timing"],
    "fine": ["fine", "late", "penalty"],
    "issue": ["issue", "borrow", "take"],
}

def reply(message):
    msg = message.lower()
    for intent, words in keywords.items():
        for w in words:
            if w in msg:
                return rules[intent]
    return "Sorry, I did not understand. Please ask the librarian."

questions = ["What time does the library open?",
             "How many books can I borrow?",
             "Is there a fine if I am late?",
             "Do you have a cricket bat?"]
for q in questions:
    print("You:", q)
    print("Bot:", reply(q))

