def simple_stem(word):
    for suffix in ["ing", "ly", "es", "s"]:
        if word.endswith(suffix) and len(word) > len(suffix) + 2:
            return word[:-len(suffix)]
    return word

lemma_dict = {"studies": "study", "studying": "study", "better": "good",
              "went": "go", "mice": "mouse", "was": "be"}

words = ["playing", "quickly", "boxes", "toys", "studies", "went", "better"]
for w in words:
    print(w, "-> stem:", simple_stem(w), "| lemma:", lemma_dict.get(w, simple_stem(w)))

